Add-Type -AssemblyName System.Drawing; foreach ($f in @('1-3', 'AK-12M')) { $b = [System.Drawing.Bitmap]::FromFile("D:\Rust\steel-front\screenshots\$f.png"); if ($b.Width -gt 1600) { $nw = 1600; $nh = [int]($b.Height * $nw / $b.Width); $nb = New-Object System.Drawing.Bitmap($nw, $nh); $g = [System.Drawing.Graphics]::FromImage($nb); $g.DrawImage($b, 0, 0, $nw, $nh); $nb.Save("D:\Rust\steel-front\screenshots\${f}s.png", [System.Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $nb.Dispose(); Write-Host "$f resized" } else { Copy-Item "D:\Rust\steel-front\screenshots\$f.png" "D:\Rust\steel-front\screenshots\${f}s.png" -Force; Write-Host "$f copied" }; $b.Dispose()